import numpy as np
import pandas as pd
from pandas import Series
from pandas import Timestamp, Timedelta
import pandas._testing as tm

def safe_eval(expr_fn):
    try:
        v = expr_fn()
        return {"ok": True, "value": v}
    except Exception as e:
        return {"ok": False, "exc_type": type(e).__name__, "exc_msg": str(e)[:200]}

# 1
s1 = Series([1,0,1,0]).astype(pd.SparseDtype(np.int64, np.nan))

def e1():
    return s1.groupby(['a','a','b','b']).min()

# 2
s2 = Series([True,False,True,False]).astype(pd.SparseDtype(bool, np.nan))

def e2():
    return s2.groupby(['a','a','b','b']).sum()

# 3
arr3 = np.array([1,2,3,4], dtype='M8[ns]')
base_ts = Timestamp(3)

def e3():
    return Series(arr3).astype(pd.SparseDtype('M8[ns]', base_ts)).groupby(['a','a','b','b']).min()

# 4
arr4 = np.array([1,2,3,4], dtype='m8[ns]')
base_td = Timedelta(3)

def e4():
    return Series(arr4).astype(pd.SparseDtype('m8[ns]', base_td)).groupby(['a','a','b','b']).sum()

# 5

def e5():
    # the PR mentions: sum on a datetime64 sparse subtype should raise
    s5 = Series(np.array([1,2,3,4], dtype='M8[ns]')).astype(pd.SparseDtype('M8[ns]', Timestamp(3)))
    return s5.sum()

# 6

def e6():
    # min surrogate: compute prod/var/skew/kurt/cumsum/cumprod/any/all
    s_td = Series(np.array([1,2,3,4], dtype='m8[ns]')).astype(pd.SparseDtype('m8[ns]', Timedelta(3)))
    s_dt = Series(np.array([1,2,3,4], dtype='M8[ns]')).astype(pd.SparseDtype('M8[ns]', Timestamp(3)))
    out = {}
    for name in ['sum','prod','var','skew','kurt','cumsum','cumprod','any','all']:
        try:
            if name in ['prod','var','skew','kurt']:
                out[name] = getattr(s_dt, name)() if name != 'sum' else getattr(s_dt,'sum')()
            else:
                # keep it simple: call on datetime for datetime-like, timedelta for timedelta-like
                if name in ['cumsum','cumprod','any','all']:
                    # PR expects error alignment for datetime and produces garbage on buggy for some timedelta ops; we just record.
                    out[name] = getattr(s_td, name)() if name in ['cumsum','cumprod','any','all'] else getattr(s_dt,name)()
                else:
                    out[name] = None
        except Exception as e:
            out[name] = {"exc_type": type(e).__name__, "exc_msg": str(e)[:200]}
    return out

results = {
    "e1_min_int64_nan": safe_eval(e1),
    "e2_sum_bool_nan": safe_eval(e2),
    "e3_min_datetime_nanfill": safe_eval(e3),
    "e4_sum_timedelta_nanfill": safe_eval(e4),
    "e5_sum_datetime_should_raise": safe_eval(e5),
    "e6_mixed_aggregations_timeline": safe_eval(e6),
}

# Record values via probe mechanism
probe("pr_sparse_groupby_examples_no_sympy", results)

